import os
import requests
from langchain_core.tools import tool

COACH_MESSAGING_BASE_URL = os.environ.get("COACH_MESSAGING_BASE_URL", "https://messaging.fitcoach.example.com/v1")
COACH_MESSAGING_API_KEY = os.environ.get("COACH_MESSAGING_API_KEY", "")


@tool
def send_workout_summary_to_coach(coach_id: str, athlete_id: str, activity_type: str, duration_minutes: float, distance_km: float = None, average_heart_rate: int = None, athlete_notes: str = "") -> dict:
    summary_lines_for_message = [f"Activity: {activity_type}", f"Duration: {duration_minutes:.0f} min"]
    if distance_km is not None:
        average_pace_minutes_per_km = duration_minutes / distance_km if distance_km > 0 else None
        summary_lines_for_message.append(f"Distance: {distance_km:.2f} km")
        if average_pace_minutes_per_km:
            summary_lines_for_message.append(f"Avg pace: {average_pace_minutes_per_km:.2f} min/km")
    if average_heart_rate is not None:
        summary_lines_for_message.append(f"Avg HR: {average_heart_rate} bpm")
    if athlete_notes:
        summary_lines_for_message.append(f"Notes: {athlete_notes}")
    outgoing_message_payload = {
        "recipient_id": coach_id,
        "sender_athlete_id": athlete_id,
        "message_type": "workout_summary",
        "body": "\n".join(summary_lines_for_message),
    }
    messaging_service_response = requests.post(
        f"{COACH_MESSAGING_BASE_URL}/messages",
        json=outgoing_message_payload,
        headers={"Authorization": f"Bearer {COACH_MESSAGING_API_KEY}"},
        timeout=10,
    )
    messaging_service_response.raise_for_status()
    delivered_message_record = messaging_service_response.json()
    return {"status": "sent", "message_id": delivered_message_record.get("id"), "coach_id": coach_id}

import sqlite3
from dataclasses import dataclass, asdict
from datetime import datetime, timedelta, timezone
from typing import Optional
from agents import function_tool

FITNESS_DB_PATH = "/var/lib/fittrack/fittrack.db"
_ALLOWED_ACCESS_LEVELS = {"view", "edit"}


@dataclass
class CoachAccessGrantResult:
    success: bool
    athlete_id: str
    coach_id: str
    access_level: Optional[str] = None
    expires_at: Optional[str] = None
    error: Optional[str] = None


def _compute_expiry(expires_in_days: Optional[int]) -> Optional[str]:
    if expires_in_days is None:
        return None
    return (datetime.now(timezone.utc) + timedelta(days=expires_in_days)).isoformat()


@function_tool
def grant_coach_access_to_training_log(athlete_id: str, coach_id: str, access_level: str, expires_in_days: Optional[int] = None) -> dict:
    normalized_level = access_level.strip().lower()
    if normalized_level not in _ALLOWED_ACCESS_LEVELS:
        return asdict(CoachAccessGrantResult(False, athlete_id, coach_id, error="access_level must be 'view' or 'edit'"))
    if athlete_id == coach_id:
        return asdict(CoachAccessGrantResult(False, athlete_id, coach_id, error="athlete cannot be their own coach"))
    if expires_in_days is not None and expires_in_days <= 0:
        return asdict(CoachAccessGrantResult(False, athlete_id, coach_id, error="expires_in_days must be positive"))

    expires_at = _compute_expiry(expires_in_days)
    granted_at = datetime.now(timezone.utc).isoformat()

    connection = sqlite3.connect(FITNESS_DB_PATH)
    try:
        with connection:
            connection.execute(
                """
                INSERT INTO training_log_access (athlete_id, grantee_id, access_level, granted_at, expires_at)
                VALUES (?, ?, ?, ?, ?)
                ON CONFLICT(athlete_id, grantee_id) DO UPDATE SET
                    access_level = excluded.access_level,
                    granted_at = excluded.granted_at,
                    expires_at = excluded.expires_at
                """,
                (athlete_id, coach_id, normalized_level, granted_at, expires_at),
            )
    finally:
        connection.close()

    return asdict(CoachAccessGrantResult(
        success=True,
        athlete_id=athlete_id,
        coach_id=coach_id,
        access_level=normalized_level,
        expires_at=expires_at,
    ))

import re
import sqlite3
from agents import function_tool

FITNESS_DB_PATH = "/var/lib/fittrack/fittrack.db"
_ID_PATTERN = re.compile(r"^[A-Za-z0-9_-]{3,64}$")


def _is_valid_identifier(value) -> bool:
    return isinstance(value, str) and bool(_ID_PATTERN.match(value))


@function_tool
def remove_coach_from_athlete(athlete_id: str, coach_id: str, delete_coach_comments: bool = False) -> dict:
    if not _is_valid_identifier(athlete_id):
        return {"success": False, "error": "invalid athlete_id"}
    if not _is_valid_identifier(coach_id):
        return {"success": False, "error": "invalid coach_id"}
    if athlete_id == coach_id:
        return {"success": False, "error": "athlete_id and coach_id must differ"}
    if not isinstance(delete_coach_comments, bool):
        return {"success": False, "error": "delete_coach_comments must be a boolean"}

    connection = sqlite3.connect(FITNESS_DB_PATH)
    try:
        with connection:
            revoke_cursor = connection.execute(
                "DELETE FROM training_log_access WHERE athlete_id = ? AND grantee_id = ?",
                (athlete_id, coach_id),
            )
            revoked_grants = revoke_cursor.rowcount
            deleted_comments = 0
            if delete_coach_comments:
                comment_cursor = connection.execute(
                    """
                    DELETE FROM workout_comments
                    WHERE author_id = ?
                      AND workout_id IN (SELECT id FROM workouts WHERE athlete_id = ?)
                    """,
                    (coach_id, athlete_id),
                )
                deleted_comments = comment_cursor.rowcount
    finally:
        connection.close()

    if revoked_grants == 0 and deleted_comments == 0:
        return {"success": False, "error": "coach had no access to this athlete's training log"}

    return {
        "success": True,
        "athlete_id": athlete_id,
        "coach_id": coach_id,
        "access_revoked": revoked_grants > 0,
        "comments_deleted": deleted_comments,
    }
